class Solution {
    public List<String> removeInvalidParentheses(String s) {
        List<String> result = new java.util.ArrayList<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        java.util.Queue<String> queue = new java.util.LinkedList<>();
        queue.offer(s);
        visited.add(s);
        boolean found = false;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String cur = queue.poll();
                if (isValid(cur)) { result.add(cur); found = true; }
                if (found) continue;
                for (int j = 0; j < cur.length(); j++) {
                    if (cur.charAt(j) != '(' && cur.charAt(j) != ')') continue;
                    String next = cur.substring(0, j) + cur.substring(j + 1);
                    if (visited.add(next)) queue.offer(next);
                }
            }
            if (found) break;
        }
        return result;
    }
    private boolean isValid(String s) {
        int count = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') count++;
            else if (c == ')') { if (--count < 0) return false; }
        }
        return count == 0;
    }
}

import java.util.*;

class Solution {
    public List<String> removeInvalidParentheses(String s) {
        int remL = 0, remR = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') remL++;
            else if (s.charAt(i) == ')') {
                if (remL > 0) remL--;
                else remR++;
            }
        }
        Set<String> result = new HashSet<>();
        dfs(s, 0, 0, remL, remR, new StringBuilder(), result);
        return new ArrayList<>(result);
    }
    private void dfs(String s, int idx, int open, int remL, int remR, StringBuilder sb, Set<String> result) {
        if (idx == s.length()) {
            if (remL == 0 && remR == 0 && open == 0) {
                result.add(sb.toString());
            }
            return;
        }
        char c = s.charAt(idx);
        int len = sb.length();
        if (c == '(' && remL > 0) {
            dfs(s, idx + 1, open, remL - 1, remR, sb, result);
        }
        if (c == ')' && remR > 0) {
            dfs(s, idx + 1, open, remL, remR - 1, sb, result);
        }
        sb.append(c);
        if (c == '(') {
            dfs(s, idx + 1, open + 1, remL, remR, sb, result);
        } else if (c == ')') {
            if (open > 0) {
                dfs(s, idx + 1, open - 1, remL, remR, sb, result);
            }
        } else {
            dfs(s, idx + 1, open, remL, remR, sb, result);
        }
        sb.setLength(len);
    }
}
